// Merge ROI root candidates with explicitly requested ids (read-only; nothing is created).
const cfg = $('Config').first().json;
const SAFE_ID = /^[A-Za-z0-9._:-]{1,200}$/;
const seeds = new Map();
for (const item of $input.all()) {
  const id = item.json.candidate_id;
  if (typeof id === 'string' && SAFE_ID.test(id)) seeds.set(id, 'roi_root:' + cfg.roi_id);
}
for (const id of cfg.candidate_ids ?? []) {
  if (typeof id === 'string' && SAFE_ID.test(id) && !seeds.has(id)) seeds.set(id, 'request');
}
if (seeds.size === 0) return [{ json: { no_candidates: true } }];
return [...seeds].map(([candidate_id, seed_source]) => ({ json: { candidate_id, seed_source } }));

// Unique candidates: requested/root candidates plus their direct children (lineage).
const byId = new Map();
for (const item of $('LUNA-P/OPS: Get Candidate').all(0)) {
  const c = item.json;
  if (c.candidate_id) byId.set(c.candidate_id, { ...c, discovered_via: 'seed' });
}
for (const item of $input.all()) {
  const c = item.json;
  if (c.candidate_id && !byId.has(c.candidate_id)) {
    byId.set(c.candidate_id, { ...c, discovered_via: 'child_of:' + c.parent_candidate_id });
  }
}
return [...byId.values()].map((c) => ({ json: c }));

// Choose which stored evaluations to review (newest candidate time first, capped).
const cfg = $('Config').first().json;
const seen = new Map();
for (const item of $input.all()) {
  const e = item.json;
  if (e.evaluation_id && !seen.has(e.evaluation_id)) {
    seen.set(e.evaluation_id, {
      evaluation_id: e.evaluation_id,
      candidate_id: e.candidate_id,
      selected_time_utc: e.candidate?.selected_time_utc ?? '',
    });
  }
}
const all = [...seen.values()].sort((a, b) => String(b.selected_time_utc).localeCompare(String(a.selected_time_utc)));
const chosen = all.slice(0, cfg.max_evaluations);
if (chosen.length === 0) return [{ json: { no_evaluations: true, evaluations_listed: 0 } }];
return chosen.map((e) => ({ json: { ...e, evaluations_listed: all.length } }));

// Scientific Evidence Formatter.
// Restructures STORED Python outputs from LUNA-P/OPS into a compact evidence pack.
// It performs no scientific computation: only selection, counts, extrema and unit ratios of
// stored values, all listed under `n8n_descriptive_summaries`.
const cfg = $('Config').first().json;
const health = $('LUNA-P/OPS: Health').first().json;
const ran = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };
const out = (name, branch = 0) => { try { return ran(name) ? $(name).all(branch) : []; } catch (e) { return []; } };
const errMsg = (j) => {
  const e = j.error ?? j;
  return String(e?.message ?? e?.description ?? JSON.stringify(e)).slice(0, 300);
};
const pairedJson = (item, sourceNode, branch = 0) => {
  try {
    const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
    return $(sourceNode).all(branch)[p?.item ?? -1]?.json ?? {};
  } catch (e) { return {}; }
};

// ---- Retrieval issues (HTTP error branches) -------------------------------------------
const retrieval_issues = [];
for (const it of out('LUNA-P/OPS: List ROI Root Candidates', 1)) {
  if (!cfg.roi_id) continue; // roi_id "" = review only the requested candidate_ids
  retrieval_issues.push({ step: 'list_roi_candidates', roi_id: cfg.roi_id, error: errMsg(it.json) });
}
for (const id of cfg.candidate_ids ?? []) {
  if (typeof id !== 'string' || !/^[A-Za-z0-9._:-]{1,200}$/.test(id)) {
    retrieval_issues.push({ step: 'request', error: 'rejected malformed candidate id', value: String(id).slice(0, 80) });
  }
}
const stepSources = [
  ['LUNA-P/OPS: Get Candidate', 'get_candidate', 'Candidates found?', 'candidate_id'],
  ['LUNA-P/OPS: List Candidate Children', 'list_children', 'LUNA-P/OPS: Get Candidate', 'candidate_id'],
  ['LUNA-P/OPS: List Candidate Evaluations', 'list_evaluations', 'Collect Candidates', 'candidate_id'],
  ['LUNA-P/OPS: Get Evaluation Manifest', 'get_manifest', 'Evaluations found?', 'evaluation_id'],
];
for (const [node, step, source, key] of stepSources) {
  for (const it of out(node, 1)) {
    const ref = pairedJson(it, source)[key];
    if (ref) retrieval_issues.push({ step, [key]: ref, error: errMsg(it.json) });
  }
}

// ---- Candidates ---------------------------------------------------------------------------
const candidates = out('Collect Candidates').map((i) => i.json).filter((c) => c.candidate_id);
const candidateById = new Map(candidates.map((c) => [c.candidate_id, c]));
const listedEvaluationIds = new Set();
const candidatesWithEvaluations = new Set();
for (const it of out('LUNA-P/OPS: List Candidate Evaluations')) {
  if (it.json.evaluation_id) {
    listedEvaluationIds.add(it.json.evaluation_id);
    candidatesWithEvaluations.add(it.json.candidate_id);
  }
}
const candidateFacts = (c) => ({
  candidate_id: c.candidate_id,
  parent_candidate_id: c.parent_candidate_id ?? null,
  site_id: c.site_id,
  terrain_window_id: c.terrain_window_id,
  latitude_deg: c.latitude_deg,
  longitude_deg: c.longitude_deg,
  terrain_elevation_m: c.terrain_elevation_m,
  observer_height_m: c.observer_height_m,
  selected_time_utc: c.selected_time_utc,
  terrain_dataset_id: c.terrain_dataset_id,
  dem_resolution_m: c.dem_resolution_m,
  terrain_nodata: c.terrain_nodata,
  coverage_bounds_m: c.coverage_bounds_m,
  coordinate_reference: c.coordinate_reference,
  validation_status: c.validation_status,
});

// ---- Provenance registry (deduplicated) ---------------------------------------------------
const provenance_registry = {};
const provKey = new Map();
const registerProvenance = (m) => {
  const p = {
    algorithm: m.method?.algorithm,
    method: m.method,
    spice: { configuration: m.spice?.configuration, moon_radii_m: m.spice?.moon_radii_m, kernel_sha256: m.spice?.kernel_sha256 },
    terrain: m.terrain,
    software: m.software,
    time_sampling: m.interval?.sampling,
  };
  const key = JSON.stringify(p);
  if (!provKey.has(key)) {
    const id = 'provenance:P' + (provKey.size + 1);
    provKey.set(key, id);
    provenance_registry[id] = p;
  }
  return provKey.get(key);
};

// ---- Per-evaluation computed evidence -----------------------------------------------------
const finite = (xs) => xs.filter((x) => typeof x === 'number' && Number.isFinite(x));
const range = (xs) => { const f = finite(xs); return f.length ? [Math.min(...f), Math.max(...f)] : null; };
const round = (x, d = 4) => (typeof x === 'number' && Number.isFinite(x) ? Number(x.toFixed(d)) : x);

const computed_evidence = [];
for (const it of out('LUNA-P/OPS: Get Evaluation Manifest')) {
  const m = it.json;
  if (!m.evaluation_id) continue;
  const o = m.outputs ?? {};
  const samples = Array.isArray(o.samples) ? o.samples : [];
  const intervals = o.intervals ?? {};
  const windowSeconds = (m.request?.duration_hours ?? 0) * 3600;
  const hz = Array.isArray(o.horizon_elevation_deg) ? o.horizon_elevation_deg : [];
  const az = Array.isArray(o.horizon_azimuth_deg) ? o.horizon_azimuth_deg : [];
  let hzMaxIdx = -1;
  hz.forEach((v, i) => { if (typeof v === 'number' && (hzMaxIdx < 0 || v > hz[hzMaxIdx])) hzMaxIdx = i; });
  const intervalStats = {};
  for (const [k, list] of Object.entries(intervals)) {
    const d = (list ?? []).map((x) => x.duration_seconds);
    intervalStats[k] = {
      interval_count: (list ?? []).length,
      truncated_interval_count: (list ?? []).filter((x) => x.truncated).length,
      longest_interval_seconds: d.length ? Math.max(...d) : 0,
    };
  }
  const parent = m.parent_candidate;
  computed_evidence.push({
    evidence_id: m.evaluation_id,
    epistemic_label: 'COMPUTED_EVIDENCE',
    provenance_ref: registerProvenance(m),
    candidate: candidateFacts(m.candidate ?? {}),
    candidate_snapshot_sha256: m.candidate_ref?.snapshot_sha256 ?? null,
    lineage: m.parent_candidate_id
      ? {
          parent_candidate_id: m.parent_candidate_id,
          parent_available: Boolean(parent),
          changes_from_parent: parent
            ? Object.fromEntries(
                ['observer_height_m', 'selected_time_utc', 'latitude_deg', 'longitude_deg', 'terrain_window_id']
                  .filter((f) => JSON.stringify(parent[f]) !== JSON.stringify(m.candidate?.[f]))
                  .map((f) => [f, { parent: parent[f], child: m.candidate?.[f] }]),
              )
            : null,
        }
      : null,
    request: m.request,
    time_window: { start_utc: m.interval?.start_utc, end_utc: m.interval?.end_utc, step_minutes: m.interval?.step_minutes, sample_count: m.interval?.sample_count },
    status: m.status,
    python_outputs: {
      visible_seconds: o.visible_seconds ?? null,
      output_sha256: o.output_sha256 ?? null,
      horizon_sample_count: o.horizon_sample_count ?? hz.length,
    },
    n8n_descriptive_summaries: {
      note: 'Counts, extrema and unit ratios of stored Python outputs; not new scientific computation.',
      visible_fraction_of_window: windowSeconds > 0 && o.visible_seconds
        ? Object.fromEntries(Object.entries(o.visible_seconds).map(([k, v]) => [k, round(v / windowSeconds)]))
        : null,
      intervals: intervalStats,
      samples_visible_count: {
        sun: samples.filter((s) => s.sun_visible).length,
        earth: samples.filter((s) => s.earth_visible).length,
        simultaneous: samples.filter((s) => s.simultaneous_visible).length,
        total: samples.length,
      },
      sun_elevation_deg_range: range(samples.map((s) => s.sun_elevation_deg)),
      earth_elevation_deg_range: range(samples.map((s) => s.earth_elevation_deg)),
      sun_azimuth_deg_range: range(samples.map((s) => s.sun_azimuth_deg)),
      terrain_horizon_elevation_deg: hz.length
        ? { min: Math.min(...finite(hz)), max: hz[hzMaxIdx], azimuth_of_max_deg: az[hzMaxIdx] ?? null }
        : null,
    },
    consistency: m.consistency,
    not_recorded: m.not_recorded ?? [],
  });
}

const evaluatedIds = new Set(computed_evidence.map((e) => e.candidate.candidate_id));
const candidates_without_evaluations = candidates
  .filter((c) => !candidatesWithEvaluations.has(c.candidate_id))
  .map((c) => ({ ...candidateFacts(c), epistemic_label: 'COMPUTED_EVIDENCE', discovered_via: c.discovered_via }));

const evidence_pack = {
  schema_version: 'luna-ops-evidence-pack/1',
  assembled_at_utc: new Date().toISOString(),
  source: {
    system: 'LUNA-P/OPS FastAPI (Python scientific authority)',
    api_base_url: cfg.api_base_url,
    api_version: health.api_version,
    lunar_core_version: health.lunar_core_version,
    access: 'read-only HTTP GET of stored records',
    endpoints: [
      'GET /api/health',
      'GET /api/rois/{roi_id}/candidates',
      'GET /api/candidates/{id}',
      'GET /api/candidates/{id}/children',
      'GET /api/candidates/{id}/evaluations',
      'GET /api/evaluations/{id}/manifest',
    ],
  },
  request: { trigger: cfg.trigger, roi_id: cfg.roi_id, candidate_ids: cfg.candidate_ids, max_evaluations: cfg.max_evaluations, question: cfg.question || null },
  scope: {
    candidates_found: candidates.length,
    candidates_with_stored_evaluations: candidatesWithEvaluations.size,
    evaluations_listed: listedEvaluationIds.size,
    evaluations_included: computed_evidence.length,
    evaluations_omitted_by_cap: Math.max(listedEvaluationIds.size - computed_evidence.length, 0),
    candidates_reviewed_via_evaluations: evaluatedIds.size,
  },
  provenance_registry,
  computed_evidence,
  candidates_without_evaluations,
  not_in_evaluation_records: [
    'DEM slope, roughness and terrain-hazard screening (only available by running GET /api/candidates/{id}/terrain-screen, a new Python computation not performed here)',
    'Mission constraints / brush thresholds (stored only with brush experiments, not with evaluations)',
    'Independent validation (all records are COMPUTED_UNVERIFIED unless status says VALIDATED)',
    'Power, thermal, communication link-budget and landing-safety analyses (outside LUNA-P/OPS scope)',
  ],
  retrieval_issues,
  epistemic_labels: {
    COMPUTED_EVIDENCE: 'Values produced and stored by the LUNA-P/OPS Python pipeline, passed through unchanged.',
    AI_INTERPRETATION: 'Model reasoning over COMPUTED_EVIDENCE; not a measurement.',
    UNVERIFIED_SUGGESTION: 'Proposed next step; not executed, not validated.',
  },
};

const known_refs = [
  ...computed_evidence.map((e) => e.evidence_id),
  ...candidates.map((c) => c.candidate_id),
  ...Object.keys(provenance_registry),
  'pack.scope', 'pack.candidates_without_evaluations', 'pack.not_in_evaluation_records', 'pack.retrieval_issues', 'pack.source',
];
return [{ json: { evidence_pack, has_computed_evidence: computed_evidence.length > 0 ? 'yes' : null, known_refs } }];

