// Scientific Recommendations: separate computed evidence, AI interpretation and unverified
// suggestions, and check the AI output against the evidence pack. Nothing is executed.
const pack = $('Scientific Evidence Formatter').first().json;
const known = new Set(pack.known_refs);
const ai = $input.first().json.output ?? {};

// Every number present in the evidence pack, plus common unit conversions and collection sizes.
const evidenceNumbers = [];
const walk = (v) => {
  if (typeof v === 'number' && Number.isFinite(v)) evidenceNumbers.push(v, v / 3600, v / 60, v * 100, v / 86400, v / 1000);
  else if (Array.isArray(v)) { evidenceNumbers.push(v.length); v.forEach(walk); }
  else if (v && typeof v === 'object') { evidenceNumbers.push(Object.keys(v).length); Object.values(v).forEach(walk); }
};
walk(pack.evidence_pack.computed_evidence);
walk(pack.evidence_pack.candidates_without_evaluations);
walk(pack.evidence_pack.scope);
walk(pack.evidence_pack.provenance_registry);
const decimals = (s) => (s.includes('.') ? s.split('.')[1].length : 0);
const numberSupported = (s) => {
  const x = Number(s);
  const tol = 0.5 * Math.pow(10, -decimals(s)) + 1e-9;
  return evidenceNumbers.some((v) => Math.abs(Math.abs(v) - Math.abs(x)) <= Math.max(tol, Math.abs(x) * 0.005));
};
const unsupportedNumbers = (text) => {
  const cleaned = String(text ?? '')
    .replace(/\d{4}-\d{2}-\d{2}(T[\d:.]+Z?)?/g, ' ')        // ISO dates/times
    .replace(/[A-Za-z_]+[-:][A-Za-z0-9_-]*\d[A-Za-z0-9_-]*/g, ' ') // ids like candidate-..., provenance:P1
    .replace(/\bSHA-?\d+\b/gi, ' ')                            // hash algorithm names
    .replace(/\b(?=[0-9a-f]*[a-f])[0-9a-f]{7,}\b/gi, ' ')      // hashes / commit ids (hex with a letter)
    .replace(/\b(?=\w*_)(?=\w*\d)\w+\b/g, ' ')                 // identifiers with underscores: LDEM_80S_20MPP_ADJ
    .replace(/\b[A-Za-z]\w*\d\w*\b/g, ' ');                    // identifiers like P1, DE421 (numbers+units like 168h are kept)
  return [...new Set((cleaned.match(/\d+(?:\.\d+)?/g) ?? []).filter((n) => !numberSupported(n)))];
};

const checks = { unresolved_refs: [], numbers_not_found_in_evidence: [], terrain_values_without_terrain_data: [], downgraded_to_interpretation: [], forced_not_executed: [] };
// The evidence pack never carries slope/roughness/hazard values, so any such quantity is unsupported.
const TERRAIN_VALUE = /\b(slopes?|roughness|boulders?|rocks?|hazards?|craters?|relief)\b[^.;]{0,40}?\d|\d[^.;]{0,25}?\b(slopes?|roughness|boulders?|rocks?|hazards?|craters?)\b/i;
const checkRefs = (where, refs) => {
  const bad = (refs ?? []).filter((r) => !known.has(r));
  if (bad.length) checks.unresolved_refs.push({ where, refs: bad });
  return bad.length === 0;
};
const checkNumbers = (where, text) => {
  const bad = unsupportedNumbers(text);
  if (bad.length) checks.numbers_not_found_in_evidence.push({ where, numbers: bad });
  const terrain = TERRAIN_VALUE.test(String(text ?? '').replace(/\d{4}-\d{2}-\d{2}(T[\d:.]+Z?)?/g, ' '));
  if (terrain) checks.terrain_values_without_terrain_data.push(where);
  return bad.length === 0 && !terrain;
};

const findings = (ai.findings ?? []).map((f) => {
  const refsOk = checkRefs('finding ' + f.finding_id, f.evidence_refs);
  const numsOk = checkNumbers('finding ' + f.finding_id, f.statement);
  let basis = f.basis;
  if (basis === 'COMPUTED_EVIDENCE' && (!refsOk || !numsOk || !(f.evidence_refs ?? []).length)) {
    basis = 'AI_INTERPRETATION';
    checks.downgraded_to_interpretation.push(f.finding_id);
  }
  return { ...f, basis, evidence_check: refsOk && numsOk ? 'refs_and_numbers_found_in_pack' : 'needs_human_check' };
});
const limitations = (ai.limitations ?? []).map((l, i) => {
  const refsOk = checkRefs('limitation ' + (i + 1), l.evidence_refs);
  const numsOk = checkNumbers('limitation ' + (i + 1), l.limitation + ' ' + l.impact);
  const ok = refsOk && numsOk;
  return { ...l, epistemic_label: 'AI_INTERPRETATION', evidence_check: ok ? 'ok' : 'needs_human_check' };
});
const recommendations = (ai.recommendations ?? []).map((r) => {
  checkRefs('recommendation ' + r.recommendation_id, r.evidence_refs);
  if (r.executed !== false) checks.forced_not_executed.push(r.recommendation_id);
  return { ...r, epistemic_label: 'UNVERIFIED_SUGGESTION', executed: false, status: 'proposed_requires_human_approval' };
});
checkNumbers('summary', ai.summary);
checkNumbers('safety_statement', ai.safety_statement);

const SAFETY = 'LUNA-P/OPS provides numerically computed geometric Sun/Earth visibility and coarse DEM screening only. ' +
  'Nothing in this review certifies landing safety, validates a site, or replaces independent analysis.';

return [{
  json: {
    schema_version: 'luna-ops-ai-review/1',
    generated_at_utc: new Date().toISOString(),
    read_only: true,
    actions_executed: [],
    computed_evidence: {
      epistemic_label: 'COMPUTED_EVIDENCE',
      authority: 'LUNA-P/OPS Python pipeline (stored records, retrieved read-only)',
      scope: pack.evidence_pack.scope,
      source: pack.evidence_pack.source,
      evidence_pack: pack.evidence_pack,
    },
    ai_interpretation: {
      epistemic_label: 'AI_INTERPRETATION',
      summary: ai.summary,
      evidence_assessment: ai.evidence_assessment,
      findings,
      limitations,
      missing_evidence: (ai.missing_evidence ?? []).map((m) => ({ ...m, epistemic_label: 'AI_INTERPRETATION' })),
    },
    unverified_suggestions: {
      epistemic_label: 'UNVERIFIED_SUGGESTION',
      note: 'Proposed only. Any new computation must be run in LUNA-P/OPS (Python) after human review.',
      recommendations,
    },
    safety_statement: { fixed: SAFETY, ai: ai.safety_statement ?? null },
    output_checks: {
      ...checks,
      passed: checks.unresolved_refs.length === 0 && checks.numbers_not_found_in_evidence.length === 0 &&
        checks.terrain_values_without_terrain_data.length === 0,
      method: 'Heuristic: cited ids must exist in the pack; numbers must match some pack value (or s/min/h/day/km/% conversion, or a count) at stated precision; ' +
        'any slope/roughness/hazard quantity is flagged because the pack has no terrain-screen data. A number matching the pack does not prove a range or comparison is correct.',
    },
  },
}];

// Deterministic report when no stored evaluation exists: no AI call, nothing executed.
const pack = $input.first().json.evidence_pack;
const pending = pack.candidates_without_evaluations.map((c) => ({
  recommendation_id: 'R-eval-' + c.candidate_id.slice(-8),
  title: 'Candidate has no stored Sun/Earth visibility evaluation',
  epistemic_label: 'UNVERIFIED_SUGGESTION',
  proposed_action: 'A person may run POST /api/candidates/' + c.candidate_id + '/evaluations in LUNA-P/OPS.',
  luna_ops_capability: 'POST /api/candidates/{id}/evaluations',
  requires_new_python_computation: true,
  executed: false,
  status: 'proposed_requires_human_approval',
}));
return [{
  json: {
    schema_version: 'luna-ops-ai-review/1',
    generated_at_utc: new Date().toISOString(),
    read_only: true,
    actions_executed: [],
    ai_called: false,
    reason: 'No stored evaluations were retrieved, so there is no computed evidence to interpret.',
    computed_evidence: { epistemic_label: 'COMPUTED_EVIDENCE', scope: pack.scope, evidence_pack: pack },
    unverified_suggestions: { epistemic_label: 'UNVERIFIED_SUGGESTION', recommendations: pending },
    retrieval_issues: pack.retrieval_issues,
  },
}];
